/**
 * AccountBillingCancel — Stripe cancel_url landing page (Phase 2b).
 * Stripe redirects here when the user closes Checkout before paying.
 * No subscription was created — we just give the user a clear back-link.
 */

import React from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import '../design-styles.css';

function CancelIcon() {
    return (
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden>
            <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="1.75" />
            <path
                d="M9 9l6 6M15 9l-6 6"
                stroke="currentColor"
                strokeWidth="1.75"
                strokeLinecap="round"
            />
        </svg>
    );
}

export default function AccountBillingCancel() {
    const { t, currentLang } = useLanguage();
    const pageDir = currentLang === 'ar' || currentLang === 'ku' ? 'rtl' : 'ltr';

    return (
        <div className="billing-cancel-page" dir={pageDir}>
            <style>{`
                .billing-cancel-page {
                    min-height: 100vh;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 32px 20px;
                    box-sizing: border-box;
                    background:
                        radial-gradient(ellipse 80% 60% at 50% 0%, rgba(34, 211, 238, 0.12) 0%, transparent 55%),
                        radial-gradient(ellipse 60% 50% at 100% 100%, rgba(59, 130, 246, 0.1) 0%, transparent 50%),
                        linear-gradient(165deg, #0b1220 0%, #111827 45%, #0f172a 100%);
                }
                .billing-cancel-card {
                    width: 100%;
                    max-width: 560px;
                    padding: 36px 32px 32px;
                    border-radius: 16px;
                    color: #f8fafc;
                    background: rgba(255, 255, 255, 0.06);
                    border: 2px solid rgba(56, 189, 248, 0.4);
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 12px 40px rgba(0, 0, 0, 0.35),
                        0 4px 18px rgba(56, 189, 248, 0.08);
                    backdrop-filter: blur(24px);
                    -webkit-backdrop-filter: blur(24px);
                }
                .billing-cancel-card__icon {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    width: 48px;
                    height: 48px;
                    margin-bottom: 16px;
                    border-radius: 12px;
                    color: #fcd34d;
                    background: rgba(251, 191, 36, 0.12);
                    border: 1px solid rgba(255, 255, 255, 0.12);
                }
                .billing-cancel-card__title {
                    margin: 0 0 8px;
                    font-size: 22px;
                    font-weight: 700;
                    letter-spacing: -0.02em;
                    line-height: 1.25;
                    color: #fff;
                }
                .billing-cancel-card__subtitle {
                    margin: 0 0 24px;
                    font-size: 13px;
                    color: #94a3b8;
                    line-height: 1.55;
                }
                .billing-cancel-note {
                    padding: 16px 18px;
                    border-radius: 12px;
                    margin-bottom: 24px;
                    font-size: 13px;
                    line-height: 1.55;
                    color: #cbd5e1;
                    background: rgba(255, 255, 255, 0.1);
                    backdrop-filter: blur(10px);
                    -webkit-backdrop-filter: blur(10px);
                    border: 2px solid rgba(56, 189, 248, 0.4);
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 2px 12px rgba(0, 0, 0, 0.12);
                }
                .billing-cancel-actions {
                    display: flex;
                    gap: 12px;
                    flex-wrap: wrap;
                }
                .billing-cancel-btn {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    flex: 1;
                    min-width: 160px;
                    padding: 12px 20px;
                    border-radius: 12px;
                    font-size: 14px;
                    font-weight: 600;
                    text-decoration: none;
                    font-family: inherit;
                    transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease, border-color 0.15s ease;
                    box-sizing: border-box;
                }
                .billing-cancel-page .billing-cancel-btn.workflow-btn-primary.ni-continue-btn {
                    position: relative;
                    overflow: hidden;
                    color: #fff !important;
                    padding: 12px 20px !important;
                    border-radius: 12px !important;
                    font-size: 14px !important;
                    font-weight: 600 !important;
                }
                .billing-cancel-page .billing-cancel-btn.btn.btn-secondary {
                    color: #ffffff !important;
                    background: rgba(255, 255, 255, 0.1) !important;
                    backdrop-filter: blur(10px);
                    -webkit-backdrop-filter: blur(10px);
                    border: 2px solid rgba(56, 189, 248, 0.4) !important;
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 2px 12px rgba(0, 0, 0, 0.12);
                }
                .billing-cancel-page .billing-cancel-btn.btn.btn-secondary:hover,
                .billing-cancel-page .billing-cancel-btn.btn.btn-secondary:focus-visible {
                    background: rgba(56, 189, 248, 0.2) !important;
                    border-color: rgba(56, 189, 248, 0.6) !important;
                    color: #ffffff !important;
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.16),
                        0 8px 24px rgba(56, 189, 248, 0.2);
                    transform: translateY(-3px);
                    outline: none;
                }
                @media (max-width: 520px) {
                    .billing-cancel-card {
                        padding: 28px 22px 24px;
                        border-radius: 16px;
                    }
                    .billing-cancel-actions {
                        flex-direction: column;
                    }
                    .billing-cancel-btn {
                        width: 100%;
                        min-width: 0;
                    }
                }
            `}</style>

            <div className="billing-cancel-card">
                <div className="billing-cancel-card__icon">
                    <CancelIcon />
                </div>

                <h1 className="billing-cancel-card__title">{t('billing_cancel_title')}</h1>
                <p className="billing-cancel-card__subtitle">{t('billing_cancel_subtitle')}</p>

                <div className="billing-cancel-note">{t('billing_cancel_no_charge_note')}</div>

                <div className="billing-cancel-actions">
                    <Link
                        to="/account/billing"
                        className="billing-cancel-btn workflow-btn-primary ni-continue-btn"
                    >
                        {t('billing_cancel_cta_back')}
                    </Link>
                    <Link to="/dashboard" className="billing-cancel-btn btn btn-secondary">
                        {t('billing_success_cta_dashboard')}
                    </Link>
                </div>
            </div>
        </div>
    );
}
