/**
 * AccountBillingSuccess — Stripe success_url landing page (Phase 2b).
 *
 * Flow on mount:
 *   1. Ask BillingContext.startFastRefresh to fast-poll /api/billing/status
 *      every 2 s for up to ~30 s, stopping early once subscriptionStatus is
 *      active or trialing.
 *   2. Render plan name + balances pulled directly from BillingContext.
 *
 * Polling lifecycle is owned entirely by BillingContext; this page only
 * declares its intent. Stripe usually delivers `checkout.session.completed`
 * within 5–30 s, well within the fast-poll budget.
 */

import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { useLanguage } from '../contexts/LanguageContext';
import { useBilling } from '../contexts/BillingContext';
import { getPlanById } from '../utils/billingDisplay';
import { ACCOUNT_GRADIENT_TEXT } from '../utils/accountTypography';
import '../design-styles.css';

const FAST_POLL_DURATION_MS = 30_000;
const FAST_POLL_INTERVAL_MS = 2_000;

const isActivatedStatus = (status) => status === 'active' || status === 'trialing';

function SuccessIcon() {
    return (
        <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden>
            <circle cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="1.75" />
            <path
                d="M8 12.5l2.5 2.5L16 9"
                stroke="currentColor"
                strokeWidth="1.75"
                strokeLinecap="round"
                strokeLinejoin="round"
            />
        </svg>
    );
}

export default function AccountBillingSuccess() {
    const { t, currentLang } = useLanguage();
    const {
        startFastRefresh,
        stopFastRefresh,
        subscriptionStatus,
        currentPlanId,
        balances,
    } = useBilling();
    const [isActive, setIsActive] = useState(isActivatedStatus(subscriptionStatus));
    const pageDir = currentLang === 'ar' || currentLang === 'ku' ? 'rtl' : 'ltr';

    useEffect(() => {
        startFastRefresh({
            durationMs: FAST_POLL_DURATION_MS,
            intervalMs: FAST_POLL_INTERVAL_MS,
            stopWhen: (snapshot) => isActivatedStatus(snapshot?.subscriptionStatus),
        });
        return () => {
            stopFastRefresh();
        };
    }, [startFastRefresh, stopFastRefresh]);

    useEffect(() => {
        if (isActivatedStatus(subscriptionStatus)) {
            setIsActive(true);
        }
    }, [subscriptionStatus]);

    const plan = currentPlanId ? getPlanById(currentPlanId) : null;
    const planLabel = plan ? t(plan.displayNameKey) : null;

    return (
        <div className="billing-success-page" dir={pageDir}>
            <style>{`
                .billing-success-page {
                    min-height: 100vh;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 32px 20px;
                    box-sizing: border-box;
                    background:
                        radial-gradient(ellipse 80% 60% at 50% 0%, rgba(34, 211, 238, 0.12) 0%, transparent 55%),
                        radial-gradient(ellipse 60% 50% at 100% 100%, rgba(59, 130, 246, 0.1) 0%, transparent 50%),
                        linear-gradient(165deg, #0b1220 0%, #111827 45%, #0f172a 100%);
                }
                .billing-success-card {
                    width: 100%;
                    max-width: 560px;
                    padding: 36px 32px 32px;
                    border-radius: 16px;
                    color: #f8fafc;
                    background: rgba(255, 255, 255, 0.06);
                    border: 2px solid rgba(56, 189, 248, 0.4);
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 12px 40px rgba(0, 0, 0, 0.35),
                        0 4px 18px rgba(56, 189, 248, 0.08);
                    backdrop-filter: blur(24px);
                    -webkit-backdrop-filter: blur(24px);
                }
                .billing-success-card__icon {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    width: 48px;
                    height: 48px;
                    margin-bottom: 16px;
                    border-radius: 12px;
                    color: #67e8f9;
                    background: rgba(34, 211, 238, 0.12);
                    border: 1px solid rgba(255, 255, 255, 0.12);
                }
                .billing-success-card__title {
                    margin: 0 0 8px;
                    font-size: 22px;
                    font-weight: 700;
                    letter-spacing: -0.02em;
                    line-height: 1.25;
                    color: #fff;
                }
                .billing-success-card__subtitle {
                    margin: 0 0 24px;
                    font-size: 13px;
                    color: #94a3b8;
                    line-height: 1.55;
                }
                .billing-success-plan {
                    padding: 18px 18px 16px;
                    border-radius: 12px;
                    margin-bottom: 24px;
                    background: rgba(255, 255, 255, 0.1);
                    backdrop-filter: blur(10px);
                    -webkit-backdrop-filter: blur(10px);
                    border: 2px solid rgba(56, 189, 248, 0.4);
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 2px 12px rgba(0, 0, 0, 0.12);
                }
                .billing-success-plan__label {
                    font-size: 11px;
                    font-weight: 700;
                    letter-spacing: 0.1em;
                    text-transform: uppercase;
                    color: #22d3ee;
                }
                .billing-success-plan__name {
                    margin-top: 6px;
                    font-size: 22px;
                    font-weight: 700;
                    color: #f8fafc;
                    letter-spacing: -0.02em;
                }
                .billing-success-plan__grid {
                    margin-top: 16px;
                    display: grid;
                    grid-template-columns: repeat(3, minmax(0, 1fr));
                    gap: 12px;
                }
                .billing-success-plan__metric-label {
                    font-size: 11px;
                    color: #94a3b8;
                    line-height: 1.35;
                }
                .billing-success-plan__metric-value {
                    margin-top: 4px;
                    font-size: 18px;
                    font-weight: 700;
                    color: #f1f5f9;
                }
                .billing-success-actions {
                    display: flex;
                    gap: 12px;
                    flex-wrap: wrap;
                }
                .billing-success-btn {
                    display: inline-flex;
                    align-items: center;
                    justify-content: center;
                    flex: 1;
                    min-width: 160px;
                    padding: 12px 20px;
                    border-radius: 12px;
                    font-size: 14px;
                    font-weight: 600;
                    text-decoration: none;
                    font-family: inherit;
                    transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease, border-color 0.15s ease;
                    box-sizing: border-box;
                }
                .billing-success-page .billing-success-btn.workflow-btn-primary.ni-continue-btn {
                    position: relative;
                    overflow: hidden;
                    color: #fff !important;
                    padding: 12px 20px !important;
                    border-radius: 12px !important;
                    font-size: 14px !important;
                    font-weight: 600 !important;
                }
                .billing-success-page .billing-success-btn.btn.btn-secondary {
                    color: #ffffff !important;
                    background: rgba(255, 255, 255, 0.1) !important;
                    backdrop-filter: blur(10px);
                    -webkit-backdrop-filter: blur(10px);
                    border: 2px solid rgba(56, 189, 248, 0.4) !important;
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.12),
                        0 2px 12px rgba(0, 0, 0, 0.12);
                }
                .billing-success-page .billing-success-btn.btn.btn-secondary:hover,
                .billing-success-page .billing-success-btn.btn.btn-secondary:focus-visible {
                    background: rgba(56, 189, 248, 0.2) !important;
                    border-color: rgba(56, 189, 248, 0.6) !important;
                    color: #ffffff !important;
                    box-shadow:
                        inset 0 1px 0 rgba(255, 255, 255, 0.16),
                        0 8px 24px rgba(56, 189, 248, 0.2);
                    transform: translateY(-3px);
                    outline: none;
                }
                @media (max-width: 520px) {
                    .billing-success-card {
                        padding: 28px 22px 24px;
                        border-radius: 16px;
                    }
                    .billing-success-plan__grid {
                        grid-template-columns: 1fr;
                        gap: 10px;
                    }
                    .billing-success-actions {
                        flex-direction: column;
                    }
                    .billing-success-btn {
                        width: 100%;
                        min-width: 0;
                    }
                }
            `}</style>

            <div className="billing-success-card">
                <div className="billing-success-card__icon">
                    <SuccessIcon />
                </div>

                <h1 className="billing-success-card__title" style={isActive ? ACCOUNT_GRADIENT_TEXT : undefined}>
                {isActive ? t('billing_success_title') : t('billing_success_pending_title')}
            </h1>
                <p className="billing-success-card__subtitle">
                {isActive ? t('billing_success_subtitle') : t('billing_success_pending_subtitle')}
            </p>

            {isActive && planLabel ? (
                    <div className="billing-success-plan">
                        <div className="billing-success-plan__label">
                        {t('account_spending_currentPlan')}
                    </div>
                        <div className="billing-success-plan__name" dir="ltr">
                            {planLabel}
                        </div>
                    {balances ? (
                            <div className="billing-success-plan__grid">
                            <div>
                                    <div className="billing-success-plan__metric-label">
                                        {t('billing_credit_voice_label')}
                                    </div>
                                    <div className="billing-success-plan__metric-value" dir="ltr">
                                        {balances.voice}
                                    </div>
                            </div>
                            <div>
                                    <div className="billing-success-plan__metric-label">
                                        {t('billing_credit_video_label')}
                                    </div>
                                    <div className="billing-success-plan__metric-value" dir="ltr">
                                        {balances.video}
                                    </div>
                            </div>
                            <div>
                                    <div className="billing-success-plan__metric-label">
                                        {t('billing_credit_search_label')}
                                    </div>
                                    <div className="billing-success-plan__metric-value" dir="ltr">
                                        {balances.search}
                                    </div>
                                </div>
                        </div>
                    ) : null}
                </div>
            ) : null}

                <div className="billing-success-actions">
                    <Link to="/dashboard" className="billing-success-btn workflow-btn-primary ni-continue-btn">
                    {t('billing_success_cta_dashboard')}
                </Link>
                    <Link to="/account/billing/portal" className="billing-success-btn btn btn-secondary">
                        {t('billing_success_cta_portal')}
                    </Link>
                </div>
            </div>
        </div>
    );
}
