import React, { useEffect, useMemo, useState } from 'react';
import {
    candidateAvatarImageProps,
    candidatePhotoUrl,
    GenderAvatar,
    inferGenderFromName,
    shouldUseGenderAvatar,
} from '../utils/candidateAssets';
import '../design-styles.css';
import { absoluteAppUrl, API_BASE_URL } from '../config/apiBase.js';
import { useLanguage } from '../contexts/LanguageContext';
import { fillI18nTemplate } from '../utils/i18nTemplate.js';
import { canonicalStageRecommendation, hasMeaningfulStageEvaluation } from '../utils/stageRecommendation.js';
import ScreeningCampaignList from '../components/screening/ScreeningCampaignList.jsx';
import ScreeningAiComparePanel from '../components/screening/ScreeningAiComparePanel.jsx';
import AiCompareTopEmailModal from '../components/screening/AiCompareTopEmailModal.jsx';
import {
    buildScreeningCampaignGroups,
    collectCampaignIdsFromCandidates,
    findCampaignGroup,
    splitVoiceCandidates,
} from '../utils/voiceCampaigns.js';

/** المرحلة لمسار المقارنة (Stage 2). */
const AI_COMPARE_STAGE = 'voice';

/** نص من n8n قد يكون "undefined" حرفياً — لا نعرض كائنات أو undefined */
function displayVoiceText(v, fallback = 'N/A') {
    if (v === undefined || v === null) return fallback;
    if (typeof v === 'object') return fallback;
    if (typeof v === 'string') {
        const t = v.trim();
        if (t === '' || /^undefined$/i.test(t) || /^null$/i.test(t)) return fallback;
        return t;
    }
    if (typeof v === 'number' && Number.isFinite(v)) return String(v);
    const s = String(v);
    if (/^undefined$/i.test(s.trim()) || /^null$/i.test(s.trim())) return fallback;
    return s;
}

/** strengths/weaknesses قد تصل كنص أو مصفوفة من n8n */
function normalizeVoiceBulletList(raw) {
    if (raw === undefined || raw === null) return [];
    if (Array.isArray(raw)) {
        return raw
            .map((x) => (typeof x === 'string' ? x.trim() : String(x).trim()))
            .filter((x) => x && !/^undefined$/i.test(x) && !/^null$/i.test(x));
    }
    if (typeof raw === 'string') {
        const t = raw.trim();
        if (!t || /^undefined$/i.test(t) || /^null$/i.test(t)) return [];
        return t
            .split(/\n+|(?:\s*,\s*)/)
            .map((s) => s.trim())
            .filter(Boolean);
    }
    return [];
}

/** مهارة: رقم /10 أو نص (كلمات) */
function formatVoiceSkill(v, naLabel, outOfTenTpl) {
    if (v === undefined || v === null) return naLabel;
    if (typeof v === 'number' && Number.isFinite(v)) return fillI18nTemplate(outOfTenTpl, { n: v });
    return displayVoiceText(v, naLabel);
}

const VoiceInterview = () => {
    const { t, currentLang } = useLanguage();
    const na = t('stageEval_notApplicable');
    const skillOutTen = t('stageEval_skillOutOfTen');

    const translateRecLabel = (canonical) => {
        switch (canonical) {
            case 'Hire':
                return t('stageEval_recHire');
            case 'Consider':
                return t('stageEval_recConsider');
            case 'Reject':
                return t('stageEval_recReject');
            case 'N/A':
                return t('stageEval_recNa');
            default:
                return canonical;
        }
    };

    const recommendationMatchesFilter = (rawRec, filterVal) => {
        if (filterVal === 'all') return true;
        const n = String(rawRec ?? '').trim().toLowerCase();
        return n === filterVal;
    };

    const [campaignGroups, setCampaignGroups] = useState({ active: [], uncategorized: null });
    /** null = campaign list; string = drill-down selection key */
    const [selectedCampaignKey, setSelectedCampaignKey] = useState(null);
    const [loading, setLoading] = useState(true);
    const [filter, setFilter] = useState('all'); // all, hire, consider, reject
    const [expandedRows, setExpandedRows] = useState(new Set());
    // كاش روابط التسجيل الموقّتة لكل مرشح: { url, expiresAt } + حالات التحميل/الخطأ.
    const [recordingUrls, setRecordingUrls] = useState({});
    const [recordingLoading, setRecordingLoading] = useState(new Set());
    const [recordingErrors, setRecordingErrors] = useState(new Set());

    // AI Compare Top (Stage 2 — مستقل عن باقي الـ webhooks)
    const [aiCompareModalOpen, setAiCompareModalOpen] = useState(false);
    const [aiCompareSubmitting, setAiCompareSubmitting] = useState(false);
    /** 'idle' | 'pending' | 'completed' | 'failed' | 'timeout' */
    const [aiCompareStatus, setAiCompareStatus] = useState('idle');
    const [aiCompareResult, setAiCompareResult] = useState(null);
    const [aiCompareRequestId, setAiCompareRequestId] = useState(null);
    const [aiComparePanelOpen, setAiComparePanelOpen] = useState(false);

    const selectedGroup = useMemo(
        () => (selectedCampaignKey ? findCampaignGroup(campaignGroups, selectedCampaignKey) : null),
        [campaignGroups, selectedCampaignKey]
    );

    const evaluatedCandidates = selectedGroup?.evaluated ?? [];
    const campaignCandidates = useMemo(() => {
        if (!selectedGroup) return [];
        const all = [...evaluatedCandidates, ...(selectedGroup.pending ?? [])];
        return all.sort((a, b) => {
            const ta = new Date(a.createdAt || a.updatedAt || 0).getTime();
            const tb = new Date(b.createdAt || b.updatedAt || 0).getTime();
            return tb - ta;
        });
    }, [selectedGroup, evaluatedCandidates]);

    const filteredCandidates = useMemo(
        () =>
            campaignCandidates.filter((c) => {
                if (!hasMeaningfulStageEvaluation(c.voiceInterviewEvaluation)) {
                    return filter === 'all';
                }
                return recommendationMatchesFilter(c.voiceInterviewEvaluation?.recommendation, filter);
            }),
        [campaignCandidates, filter]
    );

    const selectedCampaignId = selectedGroup?.campaignId ?? null;
    const canRunAiCompare = Boolean(selectedCampaignId) && evaluatedCandidates.length >= 2;

    const handlePlayRecording = async (candId) => {
        if (!candId) return;
        const cached = recordingUrls[candId];
        if (cached && Date.now() < cached.expiresAt) return; // الرابط الحالي ما زال صالحاً
        setRecordingErrors((prev) => { const n = new Set(prev); n.delete(candId); return n; });
        setRecordingLoading((prev) => new Set(prev).add(candId));
        try {
            const res = await fetch(`${API_BASE_URL}/api/candidates/${candId}/voice-recording`);
            if (!res.ok) throw new Error('failed');
            const json = await res.json();
            const url = json?.data?.url;
            const expiresIn = Number(json?.data?.expiresIn) || 3600;
            if (!url) throw new Error('no url');
            // هامش 30 ثانية قبل انتهاء الصلاحية الفعلية.
            setRecordingUrls((prev) => ({ ...prev, [candId]: { url, expiresAt: Date.now() + (expiresIn - 30) * 1000 } }));
        } catch (_) {
            setRecordingErrors((prev) => new Set(prev).add(candId));
        } finally {
            setRecordingLoading((prev) => { const n = new Set(prev); n.delete(candId); return n; });
        }
    };

    const handleStartAiCompare = async (emails) => {
        if (!selectedCampaignId) return;
        setAiCompareSubmitting(true);
        try {
            const res = await fetch(
                `${API_BASE_URL}/api/recruitment-campaigns/${encodeURIComponent(selectedCampaignId)}/ai-compare-top?stage=${AI_COMPARE_STAGE}`,
                {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ emails }),
                }
            );
            const json = await res.json();
            if (!res.ok || !json?.success) {
                setAiCompareStatus('failed');
                setAiCompareResult({ status: 'failed', emails, error: json?.message || json?.error });
                setAiComparePanelOpen(true);
                setAiCompareModalOpen(false);
                return;
            }
            setAiCompareRequestId(json.requestId);
            setAiCompareResult({ status: 'pending', emails, requestId: json.requestId });
            setAiCompareStatus('pending');
            setAiComparePanelOpen(true);
            setAiCompareModalOpen(false);
        } catch (err) {
            console.error('❌ AI compare trigger failed:', err);
            setAiCompareStatus('failed');
            setAiCompareResult({ status: 'failed', emails, error: String(err?.message || err) });
            setAiComparePanelOpen(true);
            setAiCompareModalOpen(false);
        } finally {
            setAiCompareSubmitting(false);
        }
    };

    const handleHideCampaign = async (row) => {
        const ids = [...(row?.evaluated || []), ...(row?.pending || [])]
            .map((c) => c._id || c.id)
            .filter(Boolean);
        if (ids.length === 0) {
            await fetchCandidates();
            return;
        }
        try {
            const res = await fetch(`${API_BASE_URL}/api/candidates/bulk-hide`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ ids, stage: 'voice' }),
            });
            if (!res.ok) {
                const j = await res.json().catch(() => ({}));
                console.error('❌ Campaign hide failed:', j);
            }
        } catch (err) {
            console.error('❌ Campaign hide failed:', err);
        } finally {
            setSelectedCampaignKey(null);
            await fetchCandidates();
        }
    };

    useEffect(() => {
        fetchCandidates();
    }, [currentLang]);

    useEffect(() => {
        setExpandedRows(new Set());
        setFilter('all');
        // إعادة ضبط حالة المقارنة عند تبديل الحملة + جلب آخر نتيجة محفوظة إن وُجدت
        setAiCompareModalOpen(false);
        setAiCompareSubmitting(false);
        setAiCompareStatus('idle');
        setAiCompareResult(null);
        setAiCompareRequestId(null);
        setAiComparePanelOpen(false);

        if (!selectedCampaignId) return undefined;
        let cancelled = false;
        (async () => {
            try {
                const res = await fetch(
                    `${API_BASE_URL}/api/recruitment-campaigns/${encodeURIComponent(selectedCampaignId)}/ai-compare-top?stage=${AI_COMPARE_STAGE}`
                );
                const json = await res.json();
                if (cancelled || !json?.success || !json.result) return;
                const r = json.result;
                setAiCompareResult(r);
                setAiCompareRequestId(r.requestId || null);
                if (r.status === 'completed' || r.status === 'failed') {
                    setAiCompareStatus(r.status);
                    setAiComparePanelOpen(true);
                } else if (r.status === 'pending') {
                    setAiCompareStatus('pending');
                    setAiComparePanelOpen(true);
                }
            } catch (err) {
                console.warn('⚠️ AI compare hydrate failed:', err);
            }
        })();
        return () => {
            cancelled = true;
        };
    }, [selectedCampaignKey, selectedCampaignId]);

    // Polling: عند pending نستطلع كل 3 ثوانٍ، بحد أقصى 40 محاولة (≈120 ثانية)
    useEffect(() => {
        if (aiCompareStatus !== 'pending' || !selectedCampaignId || !aiCompareRequestId) {
            return undefined;
        }
        let attempts = 0;
        let stopped = false;
        const interval = setInterval(async () => {
            attempts += 1;
            if (attempts > 40) {
                clearInterval(interval);
                if (!stopped) setAiCompareStatus('timeout');
                return;
            }
            try {
                const res = await fetch(
                    `${API_BASE_URL}/api/recruitment-campaigns/${encodeURIComponent(selectedCampaignId)}/ai-compare-top?stage=${AI_COMPARE_STAGE}`
                );
                const json = await res.json();
                const r = json?.result;
                // تجاهل النتائج التي لا تطابق آخر طلب (stale)
                if (!r || r.requestId !== aiCompareRequestId) return;
                if (r.status === 'completed' || r.status === 'failed') {
                    clearInterval(interval);
                    if (!stopped) {
                        setAiCompareResult(r);
                        setAiCompareStatus(r.status);
                    }
                }
            } catch (err) {
                console.warn('⚠️ AI compare poll failed:', err);
            }
        }, 3000);
        return () => {
            stopped = true;
            clearInterval(interval);
        };
    }, [aiCompareStatus, selectedCampaignId, aiCompareRequestId]);

    useEffect(() => {
        const previous = document.title;
        document.title = `${t('voiceInterviewPageTitle')} · ${t('companyName')}`;
        return () => {
            document.title = previous;
        };
    }, [t, currentLang]);

    // Stage 2: POST /webhook/n8n/stage2 — voiceInterviewEvaluation
    // communication / problem_solving: number أو نص | strengths / weaknesses: مصفوفة أو سطر
    const fetchCandidates = async () => {
        try {
            setLoading(true);
            const response = await fetch(`${API_BASE_URL}/api/candidates`);
            const result = await response.json();

            if (result.success && result.data) {
                const { evaluated, pending } = splitVoiceCandidates(result.data);
                const campaignIds = collectCampaignIdsFromCandidates(evaluated, pending);

                const metaByCampaignId = {};
                if (campaignIds.length > 0) {
                    try {
                        const metaRes = await fetch(
                            `${API_BASE_URL}/api/recruitment-campaigns?ids=${encodeURIComponent(campaignIds.join(','))}`
                        );
                        const metaJson = await metaRes.json();
                        if (metaJson.success && Array.isArray(metaJson.data)) {
                            for (const row of metaJson.data) {
                                if (row?.campaignId) metaByCampaignId[row.campaignId] = row;
                            }
                        }
                    } catch (metaErr) {
                        console.warn('⚠️ Campaign metadata batch fetch failed:', metaErr);
                    }
                }

                const groups = buildScreeningCampaignGroups(evaluated, pending, metaByCampaignId, {
                    uncategorized: t('screeningCampaignUncategorized'),
                    deleted: t('screeningCampaignDeleted'),
                    unknownCampaign: t('voiceInterviewPageTitle'),
                });
                setCampaignGroups(groups);
            } else {
                console.warn('⚠️ No candidates data received');
                setCampaignGroups({ active: [], uncategorized: null });
            }
        } catch (error) {
            console.error('❌ Error fetching candidates:', error);
        } finally {
            setLoading(false);
        }
    };

    const getRecommendationColor = (recommendation) => {
        switch (recommendation) {
            case 'Hire':
                return { bg: 'rgba(16, 185, 129, 0.2)', border: 'rgba(16, 185, 129, 0.4)', text: '#10B981' };
            case 'Consider':
                return { bg: 'rgba(245, 158, 11, 0.2)', border: 'rgba(245, 158, 11, 0.4)', text: '#F59E0B' };
            case 'Reject':
                return { bg: 'rgba(239, 68, 68, 0.2)', border: 'rgba(239, 68, 68, 0.4)', text: '#EF4444' };
            default:
                return { bg: 'rgba(148, 163, 184, 0.2)', border: 'rgba(148, 163, 184, 0.4)', text: '#94A3B8' };
        }
    };

    const getScoreColor = (score) => {
        if (score >= 80) return { bg: 'rgba(16, 185, 129, 0.2)', text: '#10B981' };
        if (score >= 60) return { bg: 'rgba(245, 158, 11, 0.2)', text: '#F59E0B' };
        return { bg: 'rgba(239, 68, 68, 0.2)', text: '#EF4444' };
    };

    /** Stage 2: المشاركة = رابط مقابلة الفيديو (LiveKit) وليس الصوت */
    const handleShare = async (candidate) => {
        const candidateId = candidate._id || candidate.id;
        const campaignId = candidate.campaignId;
        const q = new URLSearchParams({ candidateId: String(candidateId) });
        if (campaignId) q.set('campaignId', String(campaignId));
        const interviewLink = absoluteAppUrl(`/video-interview-call?${q.toString()}`);

        const candidateData = {
            name:
                ((candidate.full_name || candidate.fullName) || '').trim()
                || candidate.email?.split('@')[0]
                || t('stageEval_unknownCandidate'),
            position:
                candidate.position_applied_for || candidate.positionAppliedFor || na,
            score: candidate.voiceInterviewEvaluation?.overall_score || 0,
            recommendation: translateRecLabel(
                canonicalStageRecommendation(candidate.voiceInterviewEvaluation?.recommendation)
            ),
            summary: candidate.voiceInterviewEvaluation?.summary || t('stageEval_noSummary'),
            email: candidate.email || na,
            phone: candidate.phone || na,
        };

        const shareText = fillI18nTemplate(t('voiceInterview_shareBody'), {
            name: candidateData.name,
            position: candidateData.position,
            link: interviewLink,
            score: candidateData.score,
            recommendation: candidateData.recommendation,
            email: candidateData.email,
            phone: candidateData.phone,
            summary: candidateData.summary,
        });

        if (navigator.share) {
            try {
                await navigator.share({
                    title: fillI18nTemplate(t('voiceInterview_shareNavigatorTitle'), { name: candidateData.name }),
                    text: fillI18nTemplate(t('voiceInterview_shareNavigatorText'), {
                        name: candidateData.name,
                        position: candidateData.position,
                        link: interviewLink,
                    }),
                    url: interviewLink,
                });
                return;
            } catch (err) {
                if (err.name !== 'AbortError') {
                    console.error('Error sharing:', err);
                }
            }
        }

        try {
            await navigator.clipboard.writeText(shareText);
            alert(t('voiceInterview_shareCopyOk'));
        } catch (err) {
            console.error('Failed to copy:', err);
            prompt(`${t('voiceInterview_shareCopyPrompt')} `, shareText);
        }
    };

    const showCampaignList = selectedCampaignKey === null;

    const listView = (
        <div
            className="dashboard-page dashboard-page--evaalo-visual ai-head-hunter-page headhunter-campaign-history-page"
            style={{
                minHeight: '100vh',
                padding: '70px 12px 40px',
                color: '#ffffff',
                position: 'relative',
            }}
        >
            <div className="design-background design-background--evaalo-visual">
                <div className="design-orb-1" />
                <div className="design-orb-2" />
                <div className="design-orb-3" />
            </div>
            <div className="dashboard-evaalo-visual-texture" aria-hidden="true" />
            <div className="dashboard-evaalo-visual-gridlines" aria-hidden="true" />

            <div
                className="container dashboard-visual-container"
                style={{ position: 'relative', zIndex: 1, minHeight: 'calc(100vh - 250px)' }}
            >
                <div className="dashboard-grid">
                    <div className="dashboard-card dashboard-card--page-active platform-features-card">
                        {loading ? (
                            <div className="dashboard-card-body">
                                <p className="headhunter-campaign-history-empty" role="status">
                                    {t('stageEval_loading')}
                                </p>
                            </div>
                        ) : (
                            <ScreeningCampaignList
                                activeCampaigns={campaignGroups.active}
                                uncategorized={campaignGroups.uncategorized}
                                onSelect={(key) => setSelectedCampaignKey(key)}
                                onRefresh={fetchCandidates}
                                onHideCampaign={handleHideCampaign}
                                titleKey="voiceInterviewCampaignsTitle"
                                emptyKey="voiceInterviewCampaignsEmpty"
                                activeSectionKey="voiceInterviewCampaignsActiveSection"
                            />
                        )}
                    </div>
                </div>
            </div>
        </div>
    );

    const detailView = (
        <div
            className="dashboard-page dashboard-page--evaalo-visual ai-head-hunter-page headhunter-campaign-history-page"
            style={{
                minHeight: '100vh',
                padding: '70px 12px 40px',
                color: '#ffffff',
                position: 'relative',
            }}
        >
            <div className="design-background design-background--evaalo-visual">
                <div className="design-orb-1" />
                <div className="design-orb-2" />
                <div className="design-orb-3" />
            </div>
            <div className="dashboard-evaalo-visual-texture" aria-hidden="true" />
            <div className="dashboard-evaalo-visual-gridlines" aria-hidden="true" />

            <div
                className="container dashboard-visual-container"
                style={{ position: 'relative', zIndex: 1, width: '100%' }}
            >
                <div className="design-header" style={{ marginBottom: '28px' }}>
                    <div className="header-content">
                        <h1 className="design-title" style={{ marginBottom: 0 }}>
                            {selectedGroup?.title ?? t('voiceInterviewPageTitle')}
                        </h1>
                        {selectedGroup?.location ? (
                            <p className="design-subtitle" style={{ marginTop: '10px', fontSize: '15px' }}>
                                {selectedGroup.location}
                            </p>
                        ) : (
                            <p className="design-subtitle" style={{ marginTop: '10px', fontSize: '15px' }}>
                                {t('voiceInterviewSubtitle')}
                            </p>
                        )}
                    </div>
                    <div className="header-actions" style={{ flexWrap: 'wrap', gap: '10px' }}>
                        <button type="button" className="btn btn-secondary" onClick={fetchCandidates}>
                            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                <path d="M16 10C16 13.3137 13.3137 16 10 16C6.68629 16 4 13.3137 4 10C4 6.68629 6.68629 4 10 4C11.82 4 13.45 4.81 14.55 6.08" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                                <path d="M16 4V8H12" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                            </svg>
                            <span className="btn-text">{t('stageEval_refresh')}</span>
                        </button>
                        {['all', 'Hire', 'Consider', 'Reject'].map((filterOption) => {
                            const isActive = filter === filterOption.toLowerCase();
                            return (
                                <button
                                    key={filterOption}
                                    type="button"
                                    className={`btn btn-secondary stage-eval-filter-btn${isActive ? ' stage-eval-filter-btn--active' : ''}`}
                                    onClick={() => setFilter(filterOption.toLowerCase())}
                                >
                                    {filterOption === 'all' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M2.5 5H17.5M5 10H15M7.5 15H12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Hire' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <path d="M10 2.5L12.5 7.5L17.5 8.75L14.5 12.5L15.5 17.5L10 15L4.5 17.5L5.5 12.5L2.5 8.75L7.5 7.5L10 2.5Z" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Consider' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M10 6V10L13 13" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    {filterOption === 'Reject' && (
                                        <svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">
                                            <circle cx="10" cy="10" r="7.5" stroke="currentColor" strokeWidth="2"/>
                                            <path d="M7.5 7.5L12.5 12.5M12.5 7.5L7.5 12.5" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/>
                                        </svg>
                                    )}
                                    <span className="btn-text">
                                        {filterOption === 'all'
                                            ? t('stageEval_all')
                                            : filterOption === 'Hire'
                                              ? t('stageEval_recHire')
                                              : filterOption === 'Consider'
                                                ? t('stageEval_recConsider')
                                                : t('stageEval_recReject')}
                                    </span>
                                </button>
                            );
                        })}
                        {selectedCampaignId ? (
                            <button
                                type="button"
                                className="workflow-btn-primary head-hunter-submit-btn"
                                onClick={() => setAiCompareModalOpen(true)}
                                disabled={!canRunAiCompare || aiCompareStatus === 'pending'}
                                title={!canRunAiCompare ? t('aiCompareTop_needTwo') : undefined}
                            >
                                <span className="head-hunter-submit-btn__content">
                                    <svg
                                        className="head-hunter-submit-btn__ai-spark"
                                        width="22"
                                        height="22"
                                        viewBox="0 0 24 24"
                                        fill="none"
                                        xmlns="http://www.w3.org/2000/svg"
                                        aria-hidden
                                    >
                                        <path
                                            fill="currentColor"
                                            d="M9.813 15.904L9 18.75l-.813-2.846a4.5 4.5 0 00-3.09-3.09L2.25 12l2.846-.813a4.5 4.5 0 003.09-3.09L9 5.25l.813 2.846a4.5 4.5 0 003.09 3.09L15.75 12l-2.846.813a4.5 4.5 0 00-3.09 3.09zM18.259 8.715L18 9.75l-.259-1.035a3.375 3.375 0 00-2.455-2.456L14.25 6l1.036-.259a3.375 3.375 0 002.455-2.456L18 2.25l.259 1.035a3.375 3.375 0 002.456 2.456L21.75 6l-1.035.259a3.375 3.375 0 00-2.456 2.456zM16.894 20.567L16.5 21.75l-.394-1.183a2.25 2.25 0 00-1.423-1.423L13.5 18.75l1.183-.394a2.25 2.25 0 001.423-1.423l.394-1.183.394 1.183a2.25 2.25 0 001.423 1.423l1.183.394-1.183.394a2.25 2.25 0 00-1.423 1.423z"
                                        />
                                    </svg>
                                    <span className="btn-text">{t('aiCompareTop_button')}</span>
                                </span>
                            </button>
                        ) : null}
                    </div>
                </div>

                {aiComparePanelOpen && aiCompareStatus !== 'idle' ? (
                    <div style={{ marginBottom: '24px' }}>
                        <ScreeningAiComparePanel
                            status={aiCompareStatus}
                            result={aiCompareResult}
                            onDismiss={() => setAiComparePanelOpen(false)}
                        />
                    </div>
                ) : null}

                {/* Table */}
                {loading ? (
                    <div className="stage-eval-loading">
                        {t('stageEval_loading')}
                    </div>
                ) : campaignCandidates.length > 0 ? (
                    <div className="stage-eval-table-shell">
                        <div className="stage-eval-table-scroll">
                            <table className="stage-eval-table">
                                <thead>
                                    <tr style={{ 
                                        background: 'linear-gradient(180deg, rgba(30, 41, 59, 0.95) 0%, rgba(15, 23, 42, 0.95) 100%)',
                                        borderBottom: '2px solid rgba(34, 211, 238, 0.5)'
                                    }}>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '40px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}></th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'left', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            minWidth: '250px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCandidate')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colCommunicationSkills')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colEnglishFluency')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colConfidenceLevel')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colProblemSolving')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)'
                                        }}>{t('stageEval_colComputerSkills')}</th>
                                        <th style={{ 
                                            padding: '16px 8px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '13px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                            whiteSpace: 'nowrap',
                                            width: '1%',
                                            maxWidth: '118px',
                                            minWidth: '100px'
                                        }}>{t('stageEval_colRecommendation')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '13px',
                                            borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                            whiteSpace: 'nowrap',
                                            minWidth: '160px'
                                        }}>{t('stageEval_colRecording')}</th>
                                        <th style={{ 
                                            padding: '16px', 
                                            textAlign: 'center', 
                                            color: '#22d3ee', 
                                            fontWeight: 600, 
                                            fontSize: '14px', 
                                            width: '80px'
                                        }}>{t('stageEval_colShare')}</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredCandidates.length === 0 ? (
                                        <tr>
                                            <td
                                                colSpan={10}
                                                className="stage-eval-empty-cell"
                                            >
                                                {evaluatedCandidates.length === 0
                                                    ? t('voiceInterviewNoEvaluations')
                                                    : fillI18nTemplate(t('voiceInterviewNoFilterMatch'), {
                                                          filter:
                                                              filter === 'all'
                                                                  ? t('stageEval_all')
                                                                  : filter === 'hire'
                                                                    ? t('stageEval_recHire')
                                                                    : filter === 'consider'
                                                                      ? t('stageEval_recConsider')
                                                                      : t('stageEval_recReject'),
                                                      })}
                                            </td>
                                        </tr>
                                    ) : null}
                                    {filteredCandidates.map((candidate, index) => {
                                        const evaluation = candidate.voiceInterviewEvaluation;
                                        const strengthItems = normalizeVoiceBulletList(evaluation?.strengths);
                                        const weaknessItems = normalizeVoiceBulletList(evaluation?.weaknesses);
                                        const scoreColors = getScoreColor(evaluation?.overall_score || 0);
                                        const recCanon = canonicalStageRecommendation(evaluation?.recommendation);
                                        const recColors = getRecommendationColor(recCanon);
                                        const candidateId = candidate._id || candidate.id;
                                        const isExpanded = expandedRows.has(candidateId);
                                        const photoUrl = candidatePhotoUrl(candidate);
                                        
                                        const toggleRow = (e) => {
                                            // Don't expand if clicking on share button
                                            if (e.target.tagName === 'BUTTON' || e.target.closest('button')) {
                                                return;
                                            }
                                            setExpandedRows(prev => {
                                                const newSet = new Set(prev);
                                                if (newSet.has(candidateId)) {
                                                    newSet.delete(candidateId);
                                                } else {
                                                    newSet.add(candidateId);
                                                }
                                                return newSet;
                                            });
                                        };
                                        
                                        return (
                                            <React.Fragment key={candidateId}>
                                            <tr 
                                                className="stage-eval-table-row"
                                                onClick={toggleRow}
                                            >
                                                {/* Expand/Collapse Icon */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center', 
                                                    width: '40px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <svg 
                                                        width="20" 
                                                        height="20" 
                                                        viewBox="0 0 20 20" 
                                                        fill="none" 
                                                        xmlns="http://www.w3.org/2000/svg"
                                                        className="stage-eval-row-toggle"
                                                        style={{
                                                            transform: isExpanded ? 'rotate(90deg)' : 'rotate(0deg)',
                                                        }}
                                                    >
                                                        <path d="M7.5 5L12.5 10L7.5 15" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                    </svg>
                                                </td>
                                                {/* Candidate Name */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    minWidth: '250px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{ display: 'flex', alignItems: 'flex-start', gap: '12px' }}>
                                                        {/* Profile Photo */}
                                                        <div
                                                            className="candidate-avatar-ring"
                                                            style={{
                                                            width: '52px',
                                                            height: '52px',
                                                            borderRadius: '50%',
                                                            overflow: 'hidden',
                                                            flexShrink: 0,
                                                            border: '2px solid rgba(34, 211, 238, 0.35)',
                                                            background: 'linear-gradient(135deg, #06B6D4, #3B82F6)',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            boxShadow: '0 2px 8px rgba(6, 182, 212, 0.2)'
                                                        }}
                                                        >
                                                            {photoUrl ? (
                                                                <img 
                                                                    alt={((candidate.full_name || candidate.fullName) || '').trim() || t('stageEval_profilePhotoAlt')} 
                                                                    className="candidate-avatar-photo"
                                                                    decoding="async"
                                                                    draggable={false}
                                                                    {...candidateAvatarImageProps(photoUrl, 52)}
                                                                    style={{ 
                                                                        width: '100%', 
                                                                        height: '100%', 
                                                                        objectFit: 'cover' 
                                                                    }}
                                                                    onError={(e) => {
                                                                        e.target.style.display = 'none';
                                                                        const fall = e.target.nextElementSibling;
                                                                        if (fall) fall.style.display = 'flex';
                                                                    }}
                                                                />
                                                            ) : null}
                                                            {shouldUseGenderAvatar(candidate, photoUrl) ? (
                                                                <GenderAvatar
                                                                    gender={inferGenderFromName(candidate)}
                                                                    size={52}
                                                                />
                                                            ) : (
                                                                <div style={{
                                                                    display: photoUrl ? 'none' : 'flex',
                                                                    alignItems: 'center',
                                                                    justifyContent: 'center',
                                                                    width: '100%',
                                                                    height: '100%',
                                                                    fontSize: '20px',
                                                                    fontWeight: 600,
                                                                    color: '#fff'
                                                                }}>
                                                                    {((candidate.full_name || candidate.fullName)?.[0] || candidate.email?.[0] || '?').toUpperCase()}
                                                                </div>
                                                            )}
                                                        </div>
                                                        <div className="stage-eval-candidate-cell" style={{ flex: 1, minWidth: 0 }}>
                                                            <div>
                                                                {((candidate.full_name || candidate.fullName) || '').trim()
                                                                    ? (candidate.full_name || candidate.fullName).trim()
                                                                    : candidate.email?.split('@')[0] || t('stageEval_unknownCandidate')
                                                                }
                                                            </div>
                                                        <div>
                                                            {candidate.position_applied_for || candidate.positionAppliedFor || na}
                                                        </div>
                                                        {candidate.createdAt && (
                                                            <div>
                                                                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ opacity: 0.7 }}>
                                                                    <circle cx="6" cy="6" r="5" stroke="currentColor" strokeWidth="1"/>
                                                                    <path d="M6 3V6L8 8" stroke="currentColor" strokeWidth="1" strokeLinecap="round"/>
                                                                </svg>
                                                                {new Date(candidate.createdAt).toLocaleString('en-US', {
                                                                    year: 'numeric',
                                                                    month: 'short',
                                                                    day: 'numeric',
                                                                    hour: '2-digit',
                                                                    minute: '2-digit'
                                                                })}
                                                            </div>
                                                        )}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Communication */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div className="stage-eval-cell-value">
                                                        {formatVoiceSkill(evaluation?.communication, na, skillOutTen)}
                                                    </div>
                                                </td>

                                                {/* Language Fluency */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div className="stage-eval-cell-value">
                                                        {displayVoiceText(evaluation?.language_fluency, na)}
                                                    </div>
                                                </td>

                                                {/* Confidence */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div className="stage-eval-cell-value">
                                                        {displayVoiceText(evaluation?.confidence, na)}
                                                    </div>
                                                </td>

                                                {/* Problem Solving */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div className="stage-eval-cell-value">
                                                        {formatVoiceSkill(evaluation?.problem_solving, na, skillOutTen)}
                                                    </div>
                                                </td>

                                                {/* Digital Skills */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div className="stage-eval-cell-value">
                                                        {displayVoiceText(evaluation?.digital_skills, na)}
                                                    </div>
                                                </td>

                                                {/* Score + Recommendation (مثل Stage 1) */}
                                                <td style={{ 
                                                    padding: '10px 6px', 
                                                    textAlign: 'center',
                                                    verticalAlign: 'middle',
                                                    maxWidth: '118px',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <div style={{
                                                        display: 'flex',
                                                        flexDirection: 'column',
                                                        alignItems: 'center',
                                                        justifyContent: 'center',
                                                        gap: '6px',
                                                        width: '100%'
                                                    }}>
                                                        <div style={{
                                                            display: 'inline-block',
                                                            padding: '5px 10px',
                                                            borderRadius: '6px',
                                                            background: scoreColors.bg,
                                                            color: scoreColors.text,
                                                            fontWeight: 700,
                                                            fontSize: '14px',
                                                            lineHeight: 1.15
                                                        }}>
                                                            {evaluation?.overall_score || 0}%
                                                        </div>
                                                        <div style={{
                                                            display: 'inline-block',
                                                            padding: '4px 8px',
                                                            borderRadius: '5px',
                                                            background: recColors.bg,
                                                            border: `1px solid ${recColors.border}`,
                                                            color: recColors.text,
                                                            fontWeight: 600,
                                                            fontSize: '11px',
                                                            lineHeight: 1.15,
                                                            letterSpacing: '0.02em',
                                                        }}>
                                                            {translateRecLabel(recCanon)}
                                                        </div>
                                                    </div>
                                                </td>

                                                {/* Recording (presigned, lazy) */}
                                                <td style={{ 
                                                    padding: '12px 8px', 
                                                    textAlign: 'center',
                                                    verticalAlign: 'middle',
                                                    borderRight: '1px solid rgba(34, 211, 238, 0.3)',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    {!candidate.voiceRecording?.key ? (
                                                        <span style={{ color: '#64748B', fontSize: '13px' }}>—</span>
                                                    ) : recordingUrls[candidateId]?.url ? (
                                                        <audio
                                                            controls
                                                            autoPlay
                                                            preload="none"
                                                            src={recordingUrls[candidateId].url}
                                                            style={{ width: '180px', height: '36px', verticalAlign: 'middle' }}
                                                        />
                                                    ) : (
                                                        <button
                                                            type="button"
                                                            onClick={() => handlePlayRecording(candidateId)}
                                                            disabled={recordingLoading.has(candidateId)}
                                                            title={t('voiceInterview_recording')}
                                                            style={{
                                                                display: 'inline-flex',
                                                                alignItems: 'center',
                                                                gap: '6px',
                                                                padding: '7px 14px',
                                                                borderRadius: '8px',
                                                                border: '1px solid rgba(34, 211, 238, 0.4)',
                                                                background: 'rgba(34, 211, 238, 0.12)',
                                                                color: '#22d3ee',
                                                                fontSize: '13px',
                                                                fontWeight: 600,
                                                                cursor: recordingLoading.has(candidateId) ? 'wait' : 'pointer',
                                                                whiteSpace: 'nowrap'
                                                            }}
                                                        >
                                                            {recordingLoading.has(candidateId) ? (
                                                                <span>{t('voiceInterview_loading')}</span>
                                                            ) : recordingErrors.has(candidateId) ? (
                                                                <span>{t('voiceInterview_retry')}</span>
                                                            ) : (
                                                                <>
                                                                    <span style={{ fontSize: '12px' }}>▶</span>
                                                                    <span>{t('voiceInterview_play')}</span>
                                                                </>
                                                            )}
                                                        </button>
                                                    )}
                                                </td>

                                                {/* Share Button */}
                                                <td style={{ 
                                                    padding: '16px', 
                                                    textAlign: 'center',
                                                    borderLeft: '1px solid rgba(34, 211, 238, 0.1)'
                                                }}>
                                                    <button
                                                        onClick={() => handleShare(candidate)}
                                                        title={t('voiceInterviewShareTitle')}
                                                        style={{
                                                            width: '48px',
                                                            height: '48px',
                                                            borderRadius: '50%',
                                                            border: 'none',
                                                            background: 'linear-gradient(135deg, #10B981 0%, #059669 100%)',
                                                            backdropFilter: 'blur(10px)',
                                                            color: '#fff',
                                                            cursor: 'pointer',
                                                            display: 'flex',
                                                            alignItems: 'center',
                                                            justifyContent: 'center',
                                                            fontSize: '20px',
                                                            transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
                                                            boxShadow: '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)',
                                                            position: 'relative',
                                                            overflow: 'hidden'
                                                        }}
                                                        onMouseEnter={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #059669 0%, #047857 100%)';
                                                            e.currentTarget.style.boxShadow = '0 8px 24px rgba(16, 185, 129, 0.5), 0 0 0 2px rgba(34, 211, 238, 0.6)';
                                                        }}
                                                        onMouseLeave={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1) rotate(0deg)';
                                                            e.currentTarget.style.background = 'linear-gradient(135deg, #10B981 0%, #059669 100%)';
                                                            e.currentTarget.style.boxShadow = '0 4px 12px rgba(16, 185, 129, 0.3), 0 0 0 1px rgba(34, 211, 238, 0.4)';
                                                        }}
                                                        onMouseDown={(e) => {
                                                            e.currentTarget.style.transform = 'scale(0.95)';
                                                        }}
                                                        onMouseUp={(e) => {
                                                            e.currentTarget.style.transform = 'scale(1.1) rotate(360deg)';
                                                        }}
                                                    >
                                                        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                                                            <path d="M10 13a5 5 0 0 0 7.54.54l3-3a5 5 0 0 0-7.07-7.07l-1.72 1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                            <path d="M14 11a5 5 0 0 0-7.54-.54l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                                                        </svg>
                                                    </button>
                                                </td>
                                            </tr>
                                            
                                            {/* Expanded Details Row */}
                                            {isExpanded && (
                                                <tr className="stage-eval-expanded-row">
                                                    <td colSpan={10} style={{ padding: '0' }}>
                                                        <div style={{
                                                            padding: '24px',
                                                            animation: 'slideDown 0.3s ease-out'
                                                        }}>
                                                            <div style={{
                                                                display: 'grid',
                                                                gridTemplateColumns: 'repeat(2, 1fr)',
                                                                gap: '20px',
                                                                marginBottom: '20px'
                                                            }}>
                                                                {/* Summary */}
                                                                <div className="stage-eval-detail-card">
                                                                    <h4 className="stage-eval-detail-card__title">
                                                                        {t('stageEval_summary')}
                                                                    </h4>
                                                                    <p className="stage-eval-detail-card__body">
                                                                        {displayVoiceText(evaluation?.summary, t('stageEval_noSummary'))}
                                                                    </p>
                                                                </div>

                                                                {/* Weaknesses */}
                                                                <div className="stage-eval-detail-card">
                                                                    <h4 className="stage-eval-detail-card__title">
                                                                        {t('stageEval_weaknesses')}
                                                                    </h4>
                                                                    {weaknessItems.length > 0 ? (
                                                                        <ul className="stage-eval-detail-card__list">
                                                                            {weaknessItems.map((w, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{displayVoiceText(w, '')}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : evaluation?.red_flags && evaluation.red_flags.length > 0 ? (
                                                                        <ul className="stage-eval-detail-card__list">
                                                                            {evaluation.red_flags.map((flag, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{flag}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span className="stage-eval-detail-card__muted">{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Strengths */}
                                                                <div className="stage-eval-detail-card">
                                                                    <h4 className="stage-eval-detail-card__title">
                                                                        {t('stageEval_strengths')}
                                                                    </h4>
                                                                    {strengthItems.length > 0 ? (
                                                                        <ul className="stage-eval-detail-card__list">
                                                                            {strengthItems.map((strength, i) => (
                                                                                <li key={i} style={{ marginBottom: '6px' }}>{displayVoiceText(strength, '')}</li>
                                                                            ))}
                                                                        </ul>
                                                                    ) : (
                                                                        <span className="stage-eval-detail-card__muted">{t('stageEval_none')}</span>
                                                                    )}
                                                                </div>

                                                                {/* Professional Attitude */}
                                                                <div className="stage-eval-detail-card">
                                                                    <h4 className="stage-eval-detail-card__title">
                                                                        {t('stageEval_professionalAttitude')}
                                                                    </h4>
                                                                    <p className="stage-eval-detail-card__body">
                                                                        {displayVoiceText(
                                                                            evaluation?.professional_attitude ?? evaluation?.fit_for_role,
                                                                            t('stageEval_none')
                                                                        )}
                                                                    </p>
                                                                </div>

                                                                {/* Final HR Evaluation */}
                                                                <div className="stage-eval-detail-card">
                                                                    <h4 className="stage-eval-detail-card__title">
                                                                        {t('stageEval_finalHrEval')}
                                                                    </h4>
                                                                    <p className="stage-eval-detail-card__body">
                                                                        {displayVoiceText(
                                                                            evaluation?.final_hr_evaluation ??
                                                                                evaluation?.finalHrEvaluation ??
                                                                                evaluation?.recommendation,
                                                                            t('voiceInterview_noFinalHr')
                                                                        )}
                                                                    </p>
                                                                </div>
                                                            </div>
                                                        </div>
                                                    </td>
                                                </tr>
                                            )}
                                            </React.Fragment>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </div>
                    </div>
                ) : (
                    <div style={{ textAlign: 'center', padding: '60px', color: '#94A3B8' }}>
                        {t('voiceInterviewNoEvaluations')}
                    </div>
                )}

                {/* Stats — interview-eval-stat-card في index.css (زجاج سماوي عند hover) */}
                {!loading && evaluatedCandidates.length > 0 && (
                    <div
                        className="interview-eval-stats-grid"
                        style={{
                            marginTop: '30px',
                            display: 'grid',
                            gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                            gap: '20px',
                        }}
                    >
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_totalEvaluations')}</div>
                            <div style={{ color: '#F1F5F9', fontSize: '28px', fontWeight: 700 }}>{evaluatedCandidates.length}</div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recHire')}</div>
                            <div style={{ color: '#10B981', fontSize: '28px', fontWeight: 700 }}>
                                {evaluatedCandidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Hire').length}
                            </div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recConsider')}</div>
                            <div style={{ color: '#F59E0B', fontSize: '28px', fontWeight: 700 }}>
                                {evaluatedCandidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Consider').length}
                            </div>
                        </div>
                        <div className="interview-eval-stat-card">
                            <div style={{ color: '#94A3B8', fontSize: '14px', marginBottom: '8px' }}>{t('stageEval_recReject')}</div>
                            <div style={{ color: '#EF4444', fontSize: '28px', fontWeight: 700 }}>
                                {evaluatedCandidates.filter(c => c.voiceInterviewEvaluation?.recommendation === 'Reject').length}
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );

    return (
        <>
            <style>{`
                @keyframes slideDown {
                    from {
                        opacity: 0;
                        max-height: 0;
                        transform: translateY(-10px);
                    }
                    to {
                        opacity: 1;
                        max-height: 1000px;
                        transform: translateY(0);
                    }
                }
            `}</style>
            {showCampaignList ? listView : detailView}
            <AiCompareTopEmailModal
                open={aiCompareModalOpen}
                submitting={aiCompareSubmitting}
                onClose={() => setAiCompareModalOpen(false)}
                onSubmit={handleStartAiCompare}
            />
        </>
    );
};

export default VoiceInterview;





