import React, { useEffect, useRef, useState } from 'react';
import { useLanguage } from '../contexts/LanguageContext';
import { useTheme } from '../contexts/ThemeContext';

const SunIcon = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <circle cx="12" cy="12" r="4" stroke="currentColor" strokeWidth="2" />
        <path
            d="M12 2v2M12 20v2M4.93 4.93l1.41 1.41M17.66 17.66l1.41 1.41M2 12h2M20 12h2M4.93 19.07l1.41-1.41M17.66 6.34l1.41-1.41"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
        />
    </svg>
);

const MoonIcon = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <path
            d="M21 14.5A8.5 8.5 0 019.5 3 7 7 0 1021 14.5z"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
        />
    </svg>
);

const CheckIcon = () => (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <path d="M5 12l5 5L20 7" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
);

export default function ThemeToggle() {
    const { t } = useLanguage();
    const { theme, setTheme } = useTheme();
    const [open, setOpen] = useState(false);
    const wrapRef = useRef(null);

    useEffect(() => {
        if (!open) return;
        const onDocDown = (e) => {
            if (wrapRef.current && !wrapRef.current.contains(e.target)) {
                setOpen(false);
            }
        };
        const onEsc = (e) => {
            if (e.key === 'Escape') setOpen(false);
        };
        document.addEventListener('mousedown', onDocDown);
        document.addEventListener('keydown', onEsc);
        return () => {
            document.removeEventListener('mousedown', onDocDown);
            document.removeEventListener('keydown', onEsc);
        };
    }, [open]);

    const options = [
        { id: 'light', label: t('themeLight'), Icon: SunIcon },
        { id: 'dark', label: t('themeDark'), Icon: MoonIcon },
    ];

    return (
        <div className="nav-theme-toggle-wrap" ref={wrapRef}>
            <button
                type="button"
                className="nav-theme-toggle"
                aria-haspopup="menu"
                aria-expanded={open}
                aria-label={t('themeToggleAria')}
                onClick={() => setOpen((o) => !o)}
            >
                {theme === 'dark' ? <MoonIcon /> : <SunIcon />}
            </button>
            <div
                className={`nav-theme-dropdown ${open ? 'nav-theme-dropdown--open' : ''}`}
                role="menu"
                aria-hidden={!open}
            >
                {options.map(({ id, label, Icon }) => (
                    <button
                        key={id}
                        type="button"
                        role="menuitemradio"
                        aria-checked={theme === id}
                        className={`nav-theme-dropdown__option ${theme === id ? 'nav-theme-dropdown__option--active' : ''}`}
                        onClick={() => {
                            setTheme(id);
                            setOpen(false);
                        }}
                    >
                        <span className="nav-theme-dropdown__option-icon">
                            <Icon />
                        </span>
                        <span className="nav-theme-dropdown__option-label">{label}</span>
                        {theme === id ? (
                            <span className="nav-theme-dropdown__check" aria-hidden>
                                <CheckIcon />
                            </span>
                        ) : (
                            <span className="nav-theme-dropdown__check nav-theme-dropdown__check--empty" aria-hidden />
                        )}
                    </button>
                ))}
            </div>
        </div>
    );
}
