import React, { useEffect, useState } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/**
 * مودال إدخال إيميلات المستلمين قبل إطلاق "مقارنة أفضل المرشحين".
 *
 * @param {{
 *   open: boolean,
 *   submitting?: boolean,
 *   onClose: () => void,
 *   onSubmit: (emails: string[]) => void,
 * }} props
 */
export default function AiCompareTopEmailModal({ open, submitting = false, onClose, onSubmit }) {
    const { t } = useLanguage();
    const [rows, setRows] = useState(['']);
    const [error, setError] = useState('');

    useEffect(() => {
        if (open) {
            setRows(['']);
            setError('');
        }
    }, [open]);

    if (!open) return null;

    const updateRow = (index, value) => {
        setRows((prev) => {
            const next = [...prev];
            next[index] = value;
            return next;
        });
        if (error) setError('');
    };

    const addRow = () => setRows((prev) => [...prev, '']);

    const removeRow = (index) =>
        setRows((prev) => (prev.length <= 1 ? prev : prev.filter((_, i) => i !== index)));

    const handleSubmit = () => {
        const emails = [...new Set(rows.map((r) => (r || '').trim()).filter(Boolean))];
        const valid = emails.filter((e) => EMAIL_RE.test(e));
        if (valid.length === 0) {
            setError(t('aiCompareTop_invalidEmail'));
            return;
        }
        onSubmit(valid);
    };

    return (
        <div
            className="ai-compare-modal-overlay"
            role="dialog"
            aria-modal="true"
            onMouseDown={(e) => {
                if (e.target === e.currentTarget && !submitting) onClose();
            }}
        >
            <div className="ai-compare-modal">
                <div className="ai-compare-modal__header">
                    <h3>{t('aiCompareTop_modalTitle')}</h3>
                    <button
                        type="button"
                        className="ai-compare-modal__x"
                        onClick={onClose}
                        disabled={submitting}
                        aria-label={t('aiCompareTop_cancel')}
                    >
                        ×
                    </button>
                </div>

                <p className="ai-compare-modal__desc">{t('aiCompareTop_modalDesc')}</p>

                <div className="ai-compare-modal__rows">
                    {rows.map((value, index) => (
                        <div className="ai-compare-modal__row" key={index}>
                            <input
                                type="email"
                                className="ai-compare-modal__input"
                                placeholder={t('aiCompareTop_emailPlaceholder')}
                                value={value}
                                onChange={(e) => updateRow(index, e.target.value)}
                                disabled={submitting}
                            />
                            {rows.length > 1 ? (
                                <button
                                    type="button"
                                    className="ai-compare-modal__remove"
                                    onClick={() => removeRow(index)}
                                    disabled={submitting}
                                    aria-label={t('aiCompareTop_removeEmail')}
                                >
                                    ×
                                </button>
                            ) : null}
                        </div>
                    ))}
                </div>

                <button
                    type="button"
                    className="ai-compare-modal__add"
                    onClick={addRow}
                    disabled={submitting}
                >
                    + {t('aiCompareTop_addEmail')}
                </button>

                {error ? <div className="ai-compare-modal__error">{error}</div> : null}

                <div className="ai-compare-modal__actions">
                    <button
                        type="button"
                        className="btn btn-secondary"
                        onClick={onClose}
                        disabled={submitting}
                    >
                        {t('aiCompareTop_cancel')}
                    </button>
                    <button
                        type="button"
                        className="btn btn-primary"
                        onClick={handleSubmit}
                        disabled={submitting}
                    >
                        {submitting ? t('aiCompareTop_submitting') : t('aiCompareTop_submit')}
                    </button>
                </div>
            </div>
        </div>
    );
}
