import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';
import { getLegalDocs } from '../i18n/legalPages';
import LegalBullets from '../components/LegalBullets';

export default function PrivacyPage() {
    const { t, currentLang } = useLanguage();
    const { privacy: p } = getLegalDocs(currentLang);
    const isRtl = currentLang === 'ar' || currentLang === 'ku';

    const body = (
        <>
            <div className="legal-meta-pill" aria-label={p.updated}>
                <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    aria-hidden
                >
                    <rect
                        x="3"
                        y="5"
                        width="18"
                        height="16"
                        rx="2"
                        stroke="currentColor"
                        strokeWidth="1.6"
                    />
                    <path
                        d="M3 9h18M8 3v4M16 3v4"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                    />
                </svg>
                <span>{p.updated}</span>
            </div>

            <h2>{p.s1.title}</h2>
            <p className="legal-lead">{p.s1.lead}</p>

            <h2>{p.s2.title}</h2>
            <p>{p.s2.intro}</p>
            <LegalBullets items={p.s2.bullets} />

            <h2>{p.s3.title}</h2>

            <h3>{p.s3.candidate.title}</h3>
            <LegalBullets items={p.s3.candidate.bullets} />

            <h3>{p.s3.employer.title}</h3>
            <LegalBullets items={p.s3.employer.bullets} />

            <h3>{p.s3.technical.title}</h3>
            <LegalBullets items={p.s3.technical.bullets} />

            <h2>{p.s4.title}</h2>
            <p>{p.s4.intro}</p>
            <LegalBullets items={p.s4.bullets} />
            <div className="legal-callout legal-callout--warn" role="note">
                <span className="legal-callout__icon" aria-hidden>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                        <path
                            d="M12 2L2 21h20L12 2z"
                            stroke="currentColor"
                            strokeWidth="1.6"
                            strokeLinejoin="round"
                        />
                        <path
                            d="M12 10v5"
                            stroke="currentColor"
                            strokeWidth="1.6"
                            strokeLinecap="round"
                        />
                        <circle cx="12" cy="18" r="1" fill="currentColor" />
                    </svg>
                </span>
                <p>
                    <strong>{p.s4.calloutLabel}</strong>{' '}
                    {p.s4.calloutBody}
                </p>
            </div>

            <h2>{p.s5.title}</h2>
            <p>{p.s5.intro}</p>
            <LegalBullets items={p.s5.bullets} />

            <h2>{p.s6.title}</h2>
            <p>{p.s6.intro}</p>
            <LegalBullets items={p.s6.bullets} />
            <p>
                {p.s6.noSell.before}
                <strong>{p.s6.noSell.strong}</strong>
                {p.s6.noSell.after}
            </p>

            <h2>{p.s7.title}</h2>
            <p>{p.s7.intro}</p>
            <LegalBullets items={p.s7.bullets} />
            <p>{p.s7.foot}</p>

            <h2>{p.s8.title}</h2>
            <p>{p.s8.intro}</p>
            <LegalBullets items={p.s8.bullets} />

            <h2>{p.s9.title}</h2>
            <p>{p.s9.intro}</p>
            <LegalBullets items={p.s9.bullets} />

            <h2>{p.s10.title}</h2>
            <p>{p.s10.intro}</p>
            <LegalBullets items={p.s10.bullets} />

            <h2>{p.s11.title}</h2>
            <p>{p.s11.intro}</p>
            <LegalBullets items={p.s11.bullets} />
            <p>{p.s11.foot}</p>

            <h2>{p.s12.title}</h2>
            <p>{p.s12.p}</p>

            <h2>{p.s13.title}</h2>
            <p>{p.s13.p}</p>

            <h2>{p.contact.title}</h2>
            <div className="legal-contact-card">
                <p className="legal-contact-card__intro">{p.contact.intro}</p>
                <a
                    className="legal-contact-card__link"
                    href="mailto:team@evaalo.com"
                >
                    <span className="legal-contact-card__icon" aria-hidden>
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                            <rect
                                x="3"
                                y="5"
                                width="18"
                                height="14"
                                rx="2"
                                stroke="currentColor"
                                strokeWidth="1.6"
                            />
                            <path
                                d="M3 7l9 6 9-6"
                                stroke="currentColor"
                                strokeWidth="1.6"
                                strokeLinejoin="round"
                            />
                        </svg>
                    </span>
                    <span>team@evaalo.com</span>
                </a>
            </div>
        </>
    );

    return (
        <LegalPageShell title={t('privacy')} variant="features">
            {isRtl ? (
                <div className="legal-page-rtl" dir="rtl" lang={currentLang}>
                    {body}
                </div>
            ) : (
                body
            )}
        </LegalPageShell>
    );
}
