import React, { useMemo } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';

function isPlainRecord(v) {
    return v != null && typeof v === 'object' && !Array.isArray(v);
}

function pickStr(obj, keys) {
    for (const k of keys) {
        const v = obj[k];
        if (v != null && String(v).trim() !== '') return String(v).trim();
    }
    return '';
}

function normalizeComparisonRows(payload) {
    if (payload == null) return [];

    let raw = payload;
    if (typeof raw === 'string') {
        try {
            raw = JSON.parse(raw);
        } catch {
            return [];
        }
    }

    if (Array.isArray(raw)) {
        return raw.filter(isPlainRecord);
    }
    if (!isPlainRecord(raw)) return [];

    for (const key of ['comparisons', 'candidates', 'results', 'items', 'data', 'records']) {
        const v = raw[key];
        if (Array.isArray(v)) return v.filter(isPlainRecord);
    }

    if (isPlainRecord(raw.comparison)) return [raw.comparison];
    return [];
}

function normalizeRow(row, index) {
    const fileName = pickStr(row, ['fileName', 'filename', 'name', 'cvName', 'title']);
    const rankRaw = row.rank ?? row.position ?? row.order;
    const rank = typeof rankRaw === 'number' ? rankRaw : parseInt(String(rankRaw), 10);
    const scoreRaw = row.score ?? row.matchScore ?? row.rating ?? row.fitScore;
    const score = typeof scoreRaw === 'number' ? scoreRaw : parseFloat(String(scoreRaw));
    const summary = pickStr(row, ['summary', 'overview', 'analysis', 'notes', 'recommendation']);

    return {
        id: pickStr(row, ['id', 'candidateId']) || `row-${index}`,
        fileName: fileName || `CV ${index + 1}`,
        rank: Number.isFinite(rank) ? rank : index + 1,
        score: Number.isFinite(score) ? score : null,
        summary,
    };
}

export default function CvComparisonResultsWorkspace({ payload, receivedAt, loading, error }) {
    const { t } = useLanguage();

    const rows = useMemo(() => {
        const raw = normalizeComparisonRows(payload);
        const normalized = raw.map((r, i) => normalizeRow(r, i));
        return normalized.sort((a, b) => a.rank - b.rank);
    }, [payload]);

    if (loading) {
        return (
            <p className="headhunter-discovery__meta" role="status">
                {t('cvComparisonResultsLoading')}
            </p>
        );
    }

    if (error) {
        return (
            <p className="head-hunter-feedback head-hunter-feedback--err" role="alert">
                {error}
            </p>
        );
    }

    if (!rows.length) {
        return (
            <p className="headhunter-discovery__meta" role="status">
                {t('cvComparisonResultsEmpty')}
            </p>
        );
    }

    return (
        <div className="cv-comparison-results">
            {receivedAt ? (
                <p className="headhunter-discovery__meta">
                    {t('cvComparisonResultsReceivedLabel')}: {new Date(receivedAt).toLocaleString()}
                </p>
            ) : null}
            <div className="cv-comparison-results__table-wrap">
                <table className="cv-comparison-results__table">
                    <thead>
                        <tr>
                            <th scope="col">{t('cvComparisonColRank')}</th>
                            <th scope="col">{t('cvComparisonColFile')}</th>
                            <th scope="col">{t('cvComparisonColScore')}</th>
                            <th scope="col">{t('cvComparisonColSummary')}</th>
                        </tr>
                    </thead>
                    <tbody>
                        {rows.map((row) => (
                            <tr key={row.id}>
                                <td data-label={t('cvComparisonColRank')}>#{row.rank}</td>
                                <td data-label={t('cvComparisonColFile')}>{row.fileName}</td>
                                <td data-label={t('cvComparisonColScore')}>
                                    {row.score != null ? `${Math.round(row.score)}%` : '—'}
                                </td>
                                <td data-label={t('cvComparisonColSummary')}>
                                    {row.summary || '—'}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
}
