import React, { useCallback, useRef, useState } from 'react';
import { useLanguage } from '../../contexts/LanguageContext';

const MAX_FILES = 10;
const MIN_FILES = 2;
const MAX_BYTES = 5 * 1024 * 1024;

function isPdf(file) {
    const mime = (file.type || '').toLowerCase();
    const name = (file.name || '').toLowerCase();
    return mime === 'application/pdf' || name.endsWith('.pdf');
}

function formatBytes(bytes) {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/**
 * منطقة رفع سير ذاتية متعددة (PDF) — 2–10 ملفات، 5MB لكل ملف.
 */
export default function CvUploadZone({ files, onChange, disabled, error }) {
    const { t } = useLanguage();
    const inputRef = useRef(null);
    const [dragOver, setDragOver] = useState(false);

    const validateAndMerge = useCallback(
        (incoming) => {
            const next = [...files];
            const errors = [];

            for (const file of incoming) {
                if (!isPdf(file)) {
                    errors.push(t('cvComparisonErrPdfOnly'));
                    continue;
                }
                if (file.size > MAX_BYTES) {
                    errors.push(t('cvComparisonErrFileSize'));
                    continue;
                }
                if (next.length >= MAX_FILES) {
                    errors.push(t('cvComparisonErrMaxFiles'));
                    break;
                }
                const dup = next.some((f) => f.name === file.name && f.size === file.size);
                if (!dup) next.push(file);
            }

            onChange(next, errors[0] || '');
        },
        [files, onChange, t]
    );

    const onInputChange = (e) => {
        const list = e.target.files ? Array.from(e.target.files) : [];
        validateAndMerge(list);
        e.target.value = '';
    };

    const onDrop = (e) => {
        e.preventDefault();
        setDragOver(false);
        if (disabled) return;
        const list = e.dataTransfer?.files ? Array.from(e.dataTransfer.files) : [];
        validateAndMerge(list);
    };

    const removeFile = (index) => {
        const next = files.filter((_, i) => i !== index);
        onChange(next, '');
    };

    return (
        <div className="form-group head-hunter-design-field ai-cv-comparison-upload">
            <span className="form-label" id="cv-upload-label">
                {t('cvComparisonUploadLabel')}
            </span>
            <p className="ai-cv-comparison-upload__hint" id="cv-upload-hint">
                {t('cvComparisonUploadHint')}
            </p>

            <div
                className={[
                    'ai-cv-comparison-upload__dropzone',
                    dragOver ? 'ai-cv-comparison-upload__dropzone--over' : '',
                    disabled ? 'ai-cv-comparison-upload__dropzone--disabled' : '',
                ]
                    .filter(Boolean)
                    .join(' ')}
                role="button"
                tabIndex={disabled ? -1 : 0}
                aria-labelledby="cv-upload-label"
                aria-describedby="cv-upload-hint"
                onDragOver={(e) => {
                    e.preventDefault();
                    if (!disabled) setDragOver(true);
                }}
                onDragLeave={() => setDragOver(false)}
                onDrop={onDrop}
                onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        if (!disabled) inputRef.current?.click();
                    }
                }}
                onClick={() => {
                    if (!disabled) inputRef.current?.click();
                }}
            >
                <input
                    ref={inputRef}
                    type="file"
                    accept=".pdf,application/pdf"
                    multiple
                    className="ai-cv-comparison-upload__input"
                    onChange={onInputChange}
                    disabled={disabled}
                    aria-hidden
                    tabIndex={-1}
                />
                <svg
                    width="32"
                    height="32"
                    viewBox="0 0 24 24"
                    fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                    aria-hidden
                    className="ai-cv-comparison-upload__icon"
                >
                    <path
                        d="M12 16V4m0 0l-4 4m4-4l4 4M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2"
                        stroke="currentColor"
                        strokeWidth="2"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                    />
                </svg>
                <span className="ai-cv-comparison-upload__cta">{t('cvComparisonUploadCta')}</span>
                <span className="ai-cv-comparison-upload__meta">{t('cvComparisonUploadMeta')}</span>
            </div>

            {files.length > 0 ? (
                <ul className="ai-cv-comparison-upload__list" aria-label={t('cvComparisonUploadListAria')}>
                    {files.map((file, index) => (
                        <li key={`${file.name}-${file.size}-${index}`} className="ai-cv-comparison-upload__item">
                            <span className="ai-cv-comparison-upload__item-name" title={file.name}>
                                {file.name}
                            </span>
                            <span className="ai-cv-comparison-upload__item-size">{formatBytes(file.size)}</span>
                            <button
                                type="button"
                                className="ai-cv-comparison-upload__remove"
                                onClick={(e) => {
                                    e.stopPropagation();
                                    removeFile(index);
                                }}
                                disabled={disabled}
                                aria-label={`${t('cvComparisonRemoveFile')} ${file.name}`}
                            >
                                ×
                            </button>
                        </li>
                    ))}
                </ul>
            ) : null}

            {error ? (
                <p className="head-hunter-feedback head-hunter-feedback--err" role="alert">
                    {error}
                </p>
            ) : null}
        </div>
    );
}

export { MIN_FILES as CV_COMPARISON_MIN_FILES, MAX_FILES as CV_COMPARISON_MAX_FILES };
