// ============================================
// File: pages/Interview.jsx
// Purpose: Voice Interview Frontend - candidate-specific entry point
// ============================================
//
// Thin page: fetches the candidate record for display, then renders the shared
// VoiceInterviewStage UI driven by the shared useVoiceInterview() session hook.
// All session logic (WebSocket + mic + playback + timer) lives in the hook;
// all call UI lives in VoiceInterviewStage. Nothing here is duplicated.

import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import useVoiceInterview from '../hooks/useVoiceInterview';
import VoiceInterviewStage from '../components/VoiceInterviewStage';
import '../design-styles.css';

const API_BASE = import.meta.env.VITE_API_URL || 'http://localhost:5000';

const Interview = () => {
  const [searchParams] = useSearchParams();
  const candidateId = searchParams.get('candidateId');
  const language = searchParams.get('language') || 'ar';

  const [candidate, setCandidate] = useState(null);
  const [loadingCandidate, setLoadingCandidate] = useState(!!candidateId);
  const [candidateError, setCandidateError] = useState(null);

  const session = useVoiceInterview({ candidateId, language });

  useEffect(() => {
    if (!candidateId) {
      setLoadingCandidate(false);
      return;
    }
    let cancelled = false;
    setLoadingCandidate(true);
    setCandidateError(null);
    fetch(`${API_BASE}/api/candidates/${candidateId}`)
      .then((res) => {
        if (!res.ok) throw new Error('Candidate not found');
        return res.json();
      })
      .then((result) => {
        if (!cancelled && result?.data) setCandidate(result.data);
      })
      .catch((err) => {
        if (!cancelled) setCandidateError(err.message);
      })
      .finally(() => {
        if (!cancelled) setLoadingCandidate(false);
      });
    return () => { cancelled = true; };
  }, [candidateId]);

  const displayName = candidate
    ? ((candidate.full_name || candidate.fullName) || '').trim() || candidate.email?.split('@')[0] || 'Candidate'
    : 'Candidate';
  const displayPosition = candidate?.position_applied_for || candidate?.positionAppliedFor || 'Position';
  const subtitle = loadingCandidate
    ? 'Loading...'
    : candidateError
      ? 'Candidate not available'
      : `${displayName} - ${displayPosition}`;
  const candidateCardName = loadingCandidate ? 'Loading...' : candidateError ? '—' : displayName;

  return (
    <VoiceInterviewStage
      title="Voice Interview"
      subtitle={subtitle}
      candidateName={candidateCardName}
      session={session}
      canStart={!!candidateId}
      startHint={!candidateId ? 'Add candidateId to the URL to start the interview' : null}
      recordingNotice="This conversation is recorded for evaluation purposes."
    />
  );
};

export default Interview;
