import { useCallback, useEffect, useMemo, useState } from 'react';

const KEY_SAVED = 'evaalo-headhunter-saved-ids-v1';
const KEY_SHORTLIST = 'evaalo-headhunter-shortlist-ids-v1';
const KEY_REJECTED = 'evaalo-headhunter-rejected-ids-v1';

function readIdSet(storageKey) {
    try {
        const raw = localStorage.getItem(storageKey);
        if (!raw) return new Set();
        const arr = JSON.parse(raw);
        if (!Array.isArray(arr)) return new Set();
        return new Set(arr.map((x) => String(x)));
    } catch (_) {
        return new Set();
    }
}

function writeIdSet(storageKey, set) {
    try {
        localStorage.setItem(storageKey, JSON.stringify([...set]));
    } catch (_) {
        /* ignore */
    }
}

/**
 * حالة محلية لـ Save / Shortlist / Reject — جاهزة لاحقًا لاستبدالها باستدعاء API.
 */
export function useHeadHunterPersistence() {
    const [savedIds, setSavedIds] = useState(() =>
        typeof localStorage === 'undefined' ? new Set() : readIdSet(KEY_SAVED)
    );
    const [shortlistIds, setShortlistIds] = useState(() =>
        typeof localStorage === 'undefined' ? new Set() : readIdSet(KEY_SHORTLIST)
    );
    const [rejectedIds, setRejectedIds] = useState(() =>
        typeof localStorage === 'undefined' ? new Set() : readIdSet(KEY_REJECTED)
    );

    useEffect(() => {
        writeIdSet(KEY_SAVED, savedIds);
    }, [savedIds]);

    useEffect(() => {
        writeIdSet(KEY_SHORTLIST, shortlistIds);
    }, [shortlistIds]);

    useEffect(() => {
        writeIdSet(KEY_REJECTED, rejectedIds);
    }, [rejectedIds]);

    const toggleSaved = useCallback((id) => {
        const k = String(id);
        setSavedIds((prev) => {
            const next = new Set(prev);
            if (next.has(k)) next.delete(k);
            else next.add(k);
            return next;
        });
    }, []);

    const toggleShortlist = useCallback((id) => {
        const k = String(id);
        setShortlistIds((prev) => {
            const next = new Set(prev);
            if (next.has(k)) next.delete(k);
            else next.add(k);
            return next;
        });
    }, []);

    const reject = useCallback((id) => {
        const k = String(id);
        setRejectedIds((prev) => new Set(prev).add(k));
    }, []);

    const unreject = useCallback((id) => {
        const k = String(id);
        setRejectedIds((prev) => {
            const next = new Set(prev);
            next.delete(k);
            return next;
        });
    }, []);

    const isSaved = useCallback((id) => savedIds.has(String(id)), [savedIds]);
    const isShortlisted = useCallback((id) => shortlistIds.has(String(id)), [shortlistIds]);
    const isRejected = useCallback((id) => rejectedIds.has(String(id)), [rejectedIds]);

    return useMemo(
        () => ({
            savedIds,
            shortlistIds,
            rejectedIds,
            toggleSaved,
            toggleShortlist,
            reject,
            unreject,
            isSaved,
            isShortlisted,
            isRejected,
        }),
        [
            savedIds,
            shortlistIds,
            rejectedIds,
            toggleSaved,
            toggleShortlist,
            reject,
            unreject,
            isSaved,
            isShortlisted,
            isRejected,
        ]
    );
}
