/** المالية (Finance) */
const PRIORITY_FINANCE = new Set([
    'Accountant',
    'Auditor',
    'Finance Manager',
    'Financial Analyst',
    'Payroll Officer',
    'Senior Accountant',
    'Tax Specialist',
]);

function buildPrioritizedSuggestions(titles) {
    const seen = new Set();
    const hr = [];
    const marketingSales = [];
    const finance = [];
    const rest = [];
    const cmp = (a, b) => a.localeCompare(b, 'en');

    for (const t of titles) {
        if (seen.has(t)) continue;
        seen.add(t);
        if (PRIORITY_HR.has(t)) hr.push(t);
        else if (PRIORITY_MARKETING_SALES.has(t)) marketingSales.push(t);
        else if (PRIORITY_FINANCE.has(t)) finance.push(t);
        else rest.push(t);
    }

    hr.sort(cmp);
    marketingSales.sort(cmp);
    finance.sort(cmp);
    rest.sort(cmp);

    return [...hr, ...marketingSales, ...finance, ...rest];
}

export const POSITION_SUGGESTIONS = buildPrioritizedSuggestions(ALL_POSITION_TITLES);
