import React from 'react';

/** Newline-less bullet list used on Privacy / Terms / Data & Security pages. */
export default function LegalBullets({ items }) {
    if (!items?.length) return null;
    return (
        <ul>
            {items.map((line, i) => (
                <li key={i}>{line}</li>
            ))}
        </ul>
    );
}
