import React from 'react';
import LegalPageShell from '../components/LegalPageShell';
import { useLanguage } from '../contexts/LanguageContext';
import { getLegalDocs } from '../i18n/legalPages';
import LegalBullets from '../components/LegalBullets';

export default function TermsPage() {
    const { t, currentLang } = useLanguage();
    const { terms: tr } = getLegalDocs(currentLang);
    const isRtl = currentLang === 'ar' || currentLang === 'ku';

    const body = (
        <>
            <div className="legal-meta-pill" aria-label={tr.updated}>
                <svg
                    width="14"
                    height="14"
                    viewBox="0 0 24 24"
                    fill="none"
                    aria-hidden
                >
                    <rect
                        x="3"
                        y="5"
                        width="18"
                        height="16"
                        rx="2"
                        stroke="currentColor"
                        strokeWidth="1.6"
                    />
                    <path
                        d="M3 9h18M8 3v4M16 3v4"
                        stroke="currentColor"
                        strokeWidth="1.6"
                        strokeLinecap="round"
                    />
                </svg>
                <span>{tr.updated}</span>
            </div>

            <h2>{tr.s1.title}</h2>
            <p className="legal-lead">{tr.s1.lead}</p>

            <h2>{tr.s2.title}</h2>
            <p>{tr.s2.intro}</p>
            <LegalBullets items={tr.s2.bullets} />

            <h2>{tr.s3.title}</h2>
            <LegalBullets items={tr.s3.bullets} />

            <h2>{tr.s4.title}</h2>
            <p>{tr.s4.intro}</p>
            <LegalBullets items={tr.s4.bullets} />

            <h2>{tr.s5.title}</h2>
            <LegalBullets items={tr.s5.bullets} />
            <div className="legal-callout legal-callout--warn" role="note">
                <span className="legal-callout__icon" aria-hidden>
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                        <path
                            d="M12 2L2 21h20L12 2z"
                            stroke="currentColor"
                            strokeWidth="1.6"
                            strokeLinejoin="round"
                        />
                        <path
                            d="M12 10v5"
                            stroke="currentColor"
                            strokeWidth="1.6"
                            strokeLinecap="round"
                        />
                        <circle cx="12" cy="18" r="1" fill="currentColor" />
                    </svg>
                </span>
                <p>
                    <strong>{tr.s5.calloutLabel}</strong>{' '}
                    {tr.s5.calloutBody}
                </p>
            </div>

            <h2>{tr.s6.title}</h2>
            <LegalBullets items={tr.s6.bullets} />

            <h2>{tr.s7.title}</h2>
            <p>{tr.s7.intro}</p>
            <LegalBullets items={tr.s7.bullets} />

            <h2>{tr.s8.title}</h2>
            <LegalBullets items={tr.s8.bullets} />

            <h2>{tr.s9.title}</h2>
            <p>{tr.s9.p}</p>

            <h2>{tr.s10.title}</h2>
            <p>{tr.s10.p}</p>

            <h2>{tr.contact.title}</h2>
            <div className="legal-contact-card">
                <p className="legal-contact-card__intro">{tr.contact.intro}</p>
                <a
                    className="legal-contact-card__link"
                    href="mailto:team@evaalo.com"
                >
                    <span className="legal-contact-card__icon" aria-hidden>
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                            <rect
                                x="3"
                                y="5"
                                width="18"
                                height="14"
                                rx="2"
                                stroke="currentColor"
                                strokeWidth="1.6"
                            />
                            <path
                                d="M3 7l9 6 9-6"
                                stroke="currentColor"
                                strokeWidth="1.6"
                                strokeLinejoin="round"
                            />
                        </svg>
                    </span>
                    <span>team@evaalo.com</span>
                </a>
            </div>
        </>
    );

    return (
        <LegalPageShell title={t('terms')} variant="features">
            {isRtl ? (
                <div className="legal-page-rtl" dir="rtl" lang={currentLang}>
                    {body}
                </div>
            ) : (
                body
            )}
        </LegalPageShell>
    );
}
